import React from 'react';
import { Box, Typography, IconButton, Stack, Paper } from '@mui/material';
import {
  Savings,
  AccountBalanceWallet,
  Payment,
  History,
  AddCircleOutline,
  MoreHoriz,
} from '@mui/icons-material';

const menuItems = [
  { label: 'เงินดาวน์', icon: <Savings /> },
  { label: 'สินเชื่อ', icon: <AccountBalanceWallet /> },
  { label: 'ชำระเงิน', icon: <Payment /> },
  { label: 'ประวัติ', icon: <History /> },
  { label: 'สินเชื่อใหม่', icon: <AddCircleOutline /> },
  { label: 'เมนูอื่น ๆ', icon: <MoreHoriz /> },
];

const HomeMenu = () => {
  return (
    <Box p={3} bgcolor="primary">
      <Typography variant="h5" color="primary" mb={2}>
        เมนูหลัก
      </Typography>

      <Stack direction="row" flexWrap="wrap" spacing={2} useFlexGap textAlign={'center'}>
        {menuItems.map((item, index) => (
          <Paper
            key={index}
            elevation={1}
            sx={{
              width: '120px',
              height: '120px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: 3,
              backgroundColor: '#F5F5F5',
              '&:hover': {
                backgroundColor: '#E0F2F1',
                cursor: 'pointer',
              },
            }}
          >
            <IconButton color="primary">{item.icon}</IconButton>
            <Typography variant="body2" mt={1}>
              {item.label}
            </Typography>
          </Paper>
        ))}
      </Stack>
    </Box>
  );
};

export default HomeMenu;
